const unwrap = value => {
  if (Array.isArray(value)) value = value[0];
  if (value && typeof value === 'object') value = value.value ?? value.name ?? value.id;
  return value === undefined || value === null ? '' : String(value).trim();
};
return $input.all().map((item, index) => {
  const row = item.json;
  const recordId = unwrap(row.id ?? row.recordId);
  const campaignId = Number(unwrap(row.ID ?? row['EmailBison Campaign ID']));
  const campaignName = unwrap(row.Name ?? row['Campaign Name']);
  const apiKey = unwrap(row['EmailBison API (from Client)'] ?? row['EmailBison API']);
  if (!recordId.startsWith('rec')) throw new Error('Airtable Campaign record ID is missing.');
  if (!Number.isFinite(campaignId) || campaignId <= 0) throw new Error('Campaign ' + campaignName + ' has no numeric EmailBison campaign ID.');
  if (!apiKey) throw new Error('Campaign ' + campaignName + ' has no EmailBison API key.');
  return {json: {recordId, campaignId, campaignName, apiKey, baseUrl: 'https://send.dulcy.io'}, pairedItem: {item: index}};
});

const campaigns = $('Normalize Campaigns').all();
const senderResponses = $('Get Campaign Sender Emails').all();
const airtableAccounts = $('Get Airtable Email Accounts').all();

const numeric = value => {
  if (Array.isArray(value)) value = value[0];
  if (value && typeof value === 'object') value = value.value ?? value.id ?? value.name;
  const parsed = Number(value);
  return Number.isFinite(parsed) && parsed > 0 ? parsed : null;
};
const findSenderArray = value => {
  if (Array.isArray(value)) return value.flatMap(findSenderArray);
  if (!value || typeof value !== 'object') return [];
  if (numeric(value.id ?? value.sender_email_id ?? value.senderEmailId)) return [value];
  for (const key of ['sender_emails', 'senderEmails', 'emails', 'items', 'results', 'data']) {
    if (value[key] !== undefined) {
      const found = findSenderArray(value[key]);
      if (found.length) return found;
    }
  }
  return [];
};
const pageCount = response => {
  const meta = response?.json?.meta ?? response?.json?.data?.meta ?? {};
  return Math.max(1, Number(meta.last_page ?? meta.lastPage ?? 1) || 1);
};
const accountByBisonId = new Map();
for (const item of airtableAccounts) {
  const row = item.json;
  const bisonId = numeric(row['EmailBison Email ID'] ?? row['Email ID'] ?? row.fields?.['EmailBison Email ID'] ?? row.fields?.['Email ID']);
  const recordId = String(row.id ?? row.recordId ?? '').trim();
  if (bisonId && /^rec[a-zA-Z0-9]{14}$/.test(recordId)) accountByBisonId.set(bisonId, recordId);
}
if (!accountByBisonId.size) throw new Error('No Airtable Email Accounts contained a usable EmailBison Email ID or Email ID.');

const updates = [];
const skipped = [];
let responseCursor = 0;
for (let index = 0; index < campaigns.length; index++) {
  const campaign = campaigns[index].json;
  const numberOfPages = pageCount(senderResponses[responseCursor]);
  const campaignPages = senderResponses.slice(responseCursor, responseCursor + numberOfPages);
  responseCursor += numberOfPages;
  if (campaignPages.length !== numberOfPages) throw new Error('EmailBison returned incomplete pagination for ' + campaign.campaignName + '.');
  const senderObjects = findSenderArray(campaignPages.map(page => page.json));
  const senderIds = [...new Set(senderObjects.map(sender => numeric(sender?.id ?? sender?.sender_email_id ?? sender?.senderEmailId ?? sender)).filter(Boolean))];
  const unmatchedIds = senderIds.filter(id => !accountByBisonId.has(id));
  if (unmatchedIds.length) {
    skipped.push(campaign.campaignName + ' has unmatched EmailBison sender IDs: ' + unmatchedIds.join(', '));
    continue;
  }
  const linkedRecordIds = senderIds.map(id => accountByBisonId.get(id));
  updates.push({json: {
    id: campaign.recordId,
    'Email Accounts': linkedRecordIds,
    syncCampaignName: campaign.campaignName,
    syncedSenderCount: linkedRecordIds.length
  }});
}
if (responseCursor !== senderResponses.length) throw new Error('EmailBison returned ' + (senderResponses.length - responseCursor) + ' unassigned pagination page(s).');
if (skipped.length) console.log('Sender-link sync skipped: ' + skipped.join(' | '));
if (!updates.length) throw new Error('No campaign sender links were safe to update. ' + skipped.join(' | '));
return updates;
